+function Expand-HomePath {
+    param([string]$PathValue)
+
+    if ([string]::IsNullOrWhiteSpace($PathValue)) { return $PathValue }
+    if ($PathValue.StartsWith('~/')) {
+        return Join-Path $env:USERPROFILE $PathValue.Substring(2).Replace('/', '\')
+    }
+    if ($PathValue.StartsWith('~\')) {
+        return Join-Path $env:USERPROFILE $PathValue.Substring(2)
+    }
+    return $PathValue
+}
+
+function Resolve-CuratedCatalogRoot {
+    param(
+        [object]$SyncConfig,
+        [string]$ProjectRoot
+    )
+
+    $candidates = @()
+    if ($SyncConfig.curatedCatalogDir) {
+        $candidates += (Expand-HomePath -PathValue $SyncConfig.curatedCatalogDir)
+    }
+    if ($ProjectRoot -and $SyncConfig.curatedCatalogRelativePath) {
+        $candidates += Join-Path $ProjectRoot $SyncConfig.curatedCatalogRelativePath
+    }
+    if ($ProjectRoot) {
+        $candidates += Join-Path $ProjectRoot 'skills\curated'
+    }
+    $repoCurated = Join-Path (Split-Path (Split-Path $PSScriptRoot -Parent) -Parent) 'skills\curated'
+    $candidates += $repoCurated
+
+    foreach ($candidate in $candidates | Select-Object -Unique) {
+        if ($candidate -and (Test-Path $candidate)) { return $candidate }
+    }
+    return $null
+}
+
+function Convert-CuratedRoutingFrontmatter {
+    param([string]$Content)
+
+    $yaml = Get-FrontmatterYaml -Content $Content
+    if (-not $yaml) { return $null }
+
+    $result = [ordered]@{}
+    $lines = $yaml -split "`r?`n"
+    $i = 0
+    while ($i -lt $lines.Count) {
+        $line = $lines[$i]
+        if ($line -match '^([A-Za-z0-9_]+):\s*(.*)$') {
+            $key = $Matches[1]
+            $rest = $Matches[2]
+            if ($rest) {
+                $result[$key] = $rest.Trim()
+                $i++
+                continue
+            }
+
+            $items = @()
+            $skillItems = @()
+            $j = $i + 1
+            while ($j -lt $lines.Count -and $lines[$j] -match '^\s{2,}') {
+                $current = $lines[$j]
+                if ($key -eq 'skills' -and $current -match '^\s*-\s+name:\s*(.+)$') {
+                    $name = $Matches[1].Trim()
+                    $when = ''
+                    $j++
+                    while ($j -lt $lines.Count -and $lines[$j] -match '^\s{4,}') {
+                        if ($lines[$j] -match '^\s*when:\s*(.+)$') {
+                            $when = $Matches[1].Trim()
+                        }
+                        $j++
+                    }
+                    $skillItems += [pscustomobject]@{ Name = $name; When = $when }
+                    continue
+                }
+                if ($current -match '^\s*-\s*(.+)$') {
+                    $items += $Matches[1].Trim()
+                }
+                $j++
+            }
+            $result[$key] = if ($key -eq 'skills') { $skillItems } else { $items }
+            $i = $j
+            continue
+        }
+        $i++
+    }
+
+    return [pscustomobject]$result
+}
+
+function Get-CuratedRoutingCatalog {
+    param(
+        [object]$SyncConfig,
+        [string]$ProjectRoot
+    )
+
+    $root = Resolve-CuratedCatalogRoot -SyncConfig $SyncConfig -ProjectRoot $ProjectRoot
+    if (-not $root) { return @() }
+
+    $routingFiles = @(Get-ChildItem -Path $root -Filter '_routing.md' -Recurse -File -ErrorAction SilentlyContinue)
+    $catalog = @()
+    foreach ($file in $routingFiles) {
+        $content = Get-Content -LiteralPath $file.FullName -Raw -Encoding UTF8
+        $meta = Convert-CuratedRoutingFrontmatter -Content $content
+        if (-not $meta -or -not $meta.category) { continue }
+        $catalog += [pscustomobject]@{
+            Category       = [string]$meta.category
+            Purpose        = if ($meta.purpose) { [string]$meta.purpose } else { '' }
+            UseWhen        = @($meta.use_when)
+            DoNotUseWhen   = @($meta.do_not_use_when)
+            PriorityOrder  = @($meta.priority_order)
+            DefaultChain   = @($meta.default_chain)
+            SelectionRules = @($meta.selection_rules)
+            AntiPatterns   = @($meta.anti_patterns)
+            Skills         = @($meta.skills)
+            Examples       = @($meta.examples)
+            Path           = $file.FullName
+        }
+    }
+    return @($catalog | Sort-Object Category)
+}
+
+function Build-CuratedCategoryDescription {
+    param([object]$Category)
+
+    $parts = @()
+    if ($Category.Purpose) { $parts += $Category.Purpose }
+    if ($Category.UseWhen) { $parts += @($Category.UseWhen) }
+    if ($Category.Examples) { $parts += @($Category.Examples) }
+    return (($parts | Where-Object { -not [string]::IsNullOrWhiteSpace($_) }) -join ' ')
+}
+
+function Invoke-CuratedCategoryRouting {
+    param(
