+        [array]$DetectedIntents = @(),
+        [int]$TopN = 0,
+        [string]$ProjectRoot = ''
+    )
+
+    $categories = Get-CuratedRoutingCatalog -SyncConfig $SyncConfig -ProjectRoot $ProjectRoot
+    if ($categories.Count -eq 0) { return $null }
+
+    $effectiveTop = if ($TopN -gt 0) { $TopN } else { $SyncConfig.topMatches }
+    $pseudoCategories = @($categories | ForEach-Object {
+        [pscustomobject]@{
+            Name        = $_.Category
+            Description = Build-CuratedCategoryDescription -Category $_
+            SkillFile   = $_.Path
+            Source      = 'curated-category'
+        }
+    })
+
+    $topCategoryMatch = Score-SkillAgainstPrompt `
+        -Skills $pseudoCategories `
+        -UserPrompt $UserPrompt `
+        -PromptKeywordBoosts @{} `
+        -DetectedIntents $DetectedIntents `
+        -MinScore 2 `
+        -IntentBoostFloor 20 `
+        -TopN 1 | Select-Object -First 1
+
+    if (-not $topCategoryMatch) { return $null }
+
+    $topCategory = $categories | Where-Object { $_.Category -eq $topCategoryMatch.Name } | Select-Object -First 1
+    if (-not $topCategory) { return $null }
+
+    $allowedNames = @($topCategory.Skills | ForEach-Object { $_.Name } | Where-Object { $_ })
+    $categoryItems = @($CatalogItems | Where-Object { $allowedNames -contains $_.Name })
+    $shortlisted = @()
+    if ($categoryItems.Count -gt 0) {
+        $scoringItems = Apply-DescriptionOverrides -Skills $categoryItems -Overrides $SyncConfig.descriptionOverrides
+        $shortlisted = Invoke-GlobalSkillRouting `
+            -CatalogItems $scoringItems `
+            -SyncConfig $SyncConfig `
+            -UserPrompt $UserPrompt `
+            -DetectedIntents $DetectedIntents `
+            -TopN $effectiveTop
+    }
+
+    return [pscustomobject]@{
+        TopCategory       = $topCategory.Category
+        TopCategoryPath   = $topCategory.Path
+        TopCategoryScore  = $topCategoryMatch.Score
+        ForcedChain       = @($topCategory.DefaultChain)
+        PriorityOrder     = @($topCategory.PriorityOrder)
+        SelectionRules    = @($topCategory.SelectionRules)
+        ShortlistedSkills = @($shortlisted)
+    }
